contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depAmount, uint withdrawFirst) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmount)); require(depAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depAmount, "insufficient balance");

        c.deposit{value: depAmount}(); if (__ESBMC_reverted()) return;

        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;

        assert(
            (reverted && cBalAfter == cBalBefore && thisBalAfter == thisBalBefore) ||
            (!reverted && cBalBefore + thisBalBefore == cBalAfter + thisBalAfter)
        );
    }

    receive() external payable {}
}

